def compute_block_coverage(inp):
    h, w = len(inp), len(inp[0])
    coverage = [[0] * w for _ in range(h)]
    for r in range(h - 1):
        for c in range(w - 1):
            if (inp[r][c] == 2 and inp[r][c+1] == 2 and
                inp[r+1][c] == 2 and inp[r+1][c+1] == 2):
                for dr in [0, 1]:
                    for dc in [0, 1]:
                        coverage[r+dr][c+dc] += 1
    return coverage

